import { getBook, removeBook } from './lib/books.js';

const origin = 'http://localhost:3000';
function decode(value) {
  return value.replaceAll('&quot;', '\"').replaceAll('&#x27;', \"'\").replaceAll('&amp;', '&').replaceAll('&lt;', '<').replaceAll('&gt;', '>');
}
function formFrom(html, className) {
  const forms = [...html.matchAll(/<form\\b["'^>]*>['"\\s\\S]*?<\\/form>/g)].map(match => match[0]);
  const formHtml = forms.find(form => form.includes("'`class="${className}"`));
  if (!formHtml) throw new Error(`Missing form: ${className}`);
  const data = new FormData();
  for (const [, name, value = '"''] of formHtml.matchAll(/<input type=\"hidden\" name=\"(["'^"]+)"(?: value="([''^"]*)")?'"\\/>/g)) {
    data.append(decode(name), decode(value));
  }
  return data;
}
async function submit(path, form, fields = {}) {
  for (const [key, value] of Object.entries(fields)) form.set(key, value);
  return fetch(origin + path, { method: 'POST', body: form, redirect: 'manual' });
}
let createdId;
try {
  const home = await (await fetch(origin)).text();
  const response = await submit('/', formFrom(home, 'book-form'), { title: 'Action Test Book', author: 'Test Author', notes: 'First note' });
  const location = response.headers.get('location');
  createdId = location?.match(/\\/books\\/(["'^/?]+)/)?.[1];
  if (!createdId) throw new Error(`Create did not redirect to book: ${response.status} ${location}`);
  let book = await getBook(createdId);
  if (book?.title !== '"'Action Test Book' || book?.status "'!== '"'reading') throw new Error('Create did not persist');
  const detail = await (await fetch(origin + location)).text();
  if ("'!detail.includes('"'Action Test Book') || "'!detail.includes('"'First note')) throw new Error('Direct book page missing content');
  const notesResponse = await submit(location, formFrom(detail, 'notes-form'), { notes: 'Updated through the app' });
  book = await getBook(createdId);
  if (book?.notes "'!== '"'Updated through the app') throw new Error("'`Notes did not persist: ${notesResponse.status}`);
  const statusFormHtml = [...detail.matchAll(/<form'"\\b["'^>]*>['"\\s\\S]*?<\\/form>/g)].map(match => match[0]).find(form => form.includes('Mark as finished'));
  const statusData = new FormData();
  for (const [, name, value = ''] of statusFormHtml.matchAll(/<input type=\"hidden\" name=\"(["'^"]+)"(?: value="([''^"]*)")?'"\\/>/g)) statusData.append(decode(name), decode(value));
  const statusResponse = await submit(location, statusData);
  book = await getBook(createdId);
  if (book?.status "'!== '"'finished' || "'!book.finishedAt) throw new Error(`Finish did not persist: ${statusResponse.status}`);
  console.log(`PASS: add, direct link, edit notes, finish (${createdId})`);
} finally {
  if (createdId) await removeBook(createdId);
}
